 54 | async function classifyOne(file: File, isFirst: boolean): Promise<ClassifyResult> {
 55 |   const fd = new FormData();
 56 |   fd.append("file", file);
 57 |   // Order prior: first upload is EXPECTED to be the resume (+2 resume hint),
 58 |   // but content always decides — a COE uploaded first still scores COE.
 59 |   fd.append("is_first", isFirst ? "true" : "false");
 60 |   let res: Response;
 61 |   try {
 62 |     // Accept: application/json forces Laravel to answer validation failures
 63 |     // as JSON (422) instead of an HTML redirect the browser would follow and
 64 |     // misread as an empty result.
 65 |     res = await fetch("/api/v1/landing/classify-document", {
 66 |       method: "POST",
 67 |       body: fd,
 68 |       headers: { Accept: "application/json" },
 69 |     });
 70 |   } catch {
 71 |     throw new Error("Cannot reach backend (:8000). Is `php artisan serve` running?");
 72 |   }
 73 |   const json: any = await res.json().catch(() => ({}));
 74 |   if (!res.ok || json.success === false) {
 75 |     throw new Error(json.error_message || json.message || `Classify failed (${res.status})`);
 76 |   }
 77 |   // Normalize ANY backend shape so render can never crash (docx/odd files).
 78 |   const scores: Record<string, number> =
 79 |     json.scores && typeof json.scores === "object" ? json.scores : {};
 80 |   for (const t of ["Resume", "COE", "Certificate", "Credential", "Others"]) {
 81 |     const v = Number(scores[t]);
 82 |     scores[t] = Number.isFinite(v) ? v : 0;
 83 |   }
 84 |   const signals = json.signals && typeof json.signals === "object" ? json.signals : {};
 85 |   return {
 86 |     predicted_type:
 87 |       typeof json.predicted_type === "string" && json.predicted_type ? json.predicted_type : "Others",
 88 |     confidence: Number.isFinite(Number(json.confidence)) ? Number(json.confidence) : 0,
 89 |     scores,
 90 |     reasons: Array.isArray(json.reasons) ? json.reasons.map(String) : ["No signals returned."],
 91 |     signals: {
 92 |       has_email: signals.has_email === true,
 93 |       has_phone: signals.has_phone === true,
 94 |       sections: Array.isArray(signals.sections) ? signals.sections.map(String) : [],
 95 |       char_count: Number.isFinite(Number(signals.char_count)) ? Number(signals.char_count) : 0,
 96 |     },
 97 |     text_preview: typeof json.text_preview === "string" ? json.text_preview : undefined,
 98 |     text_extraction:
 99 |       json.text_extraction && typeof json.text_extraction === "object" ? json.text_extraction : undefined,
100 |     diagnostics:
101 |       json.diagnostics && typeof json.diagnostics === "object" ? json.diagnostics : undefined,
102 |     classifier_version: typeof json.classifier_version === "string" ? json.classifier_version : undefined,
103 |   };
104 | }
