214 |     /**
215 |      * Public content-based classifier for the isolated accuracy test page
216 |      * (and the future single-dropzone apply flow). Accepts any resume /
217 |      * supporting document and predicts Resume | COE | Certificate |
218 |      * Credential | Others.
219 |      *
220 |      * Three-signal fusion: CONTENT decides; filename is a small hint;
221 |      * is_first (first upload, expected resume slot) is a small +2 resume
222 |      * prior that never overrules strong document phrasing.
223 |      */
224 |     public function classifyDocument(Request $request): JsonResponse
225 |     {
226 |         $request->validate([
227 |             'file' => ['required', 'file', self::uploadExtensionRule(), 'max:20480'],
228 |             // NOTE: 'boolean' rule rejects the strings FormData sends
229 |             // ("true"/"false"/"1"/"0"), so accept those explicitly and cast below.
230 |             'is_first' => ['sometimes', 'in:true,false,1,0,yes,no,on,off'],
231 |         ]);
232 | 
233 |         $isFirst = filter_var($request->input('is_first', false), FILTER_VALIDATE_BOOLEAN);
234 |         $originalName = $request->file('file')->getClientOriginalName() ?: 'document';
235 |         $storedPath = $request->file('file')->store('classify-tmp', 'local');
236 |         try {
237 |             $fullPath = Storage::disk('local')->path($storedPath);
238 |             $result = $this->nlp->classifyDocument($fullPath, $originalName, $isFirst);
239 |         } finally {
240 |             if (Storage::disk('local')->exists($storedPath)) {
241 |                 Storage::disk('local')->delete($storedPath);
242 |             }
243 |         }
244 | 
245 |         if (! ($result['ok'] ?? false)) {
246 |             return response()->json([
247 |                 'success' => false,
248 |                 'error_message' => $result['error'] ?? 'Document classification failed.',
249 |             ], 502);
250 |         }
251 | 
252 |         return response()->json(array_merge(['success' => true], $result['data'] ?? []));
253 |     }
