244 |     /**
245 |      * Content-based single-dropzone classifier: predicts
246 |      * Resume | COE | Certificate | Credential | Others from CONTENT.
247 |      * $isFirst marks the first upload (expected resume slot): a small +2
248 |      * resume prior that never overrules strong document phrasing.
249 |      * Returns ['ok' => bool, 'data' => ?array, 'error' => ?string].
250 |      */
251 |     public function classifyDocument(string $filePath, string $originalName, bool $isFirst = false, int $timeoutSeconds = 60): array
252 |     {
253 |         if (!is_file($filePath)) {
254 |             return ['ok' => false, 'data' => null, 'error' => "Document file not found at {$filePath}"];
255 |         }
256 | 
257 |         try {
258 |             $response = Http::timeout($timeoutSeconds)
259 |                 ->attach('file', file_get_contents($filePath), $originalName)
260 |                 ->post("{$this->baseUrl}/classify-document", [
261 |                     'is_first' => $isFirst ? 'true' : 'false',
262 |                 ]);
263 | 
264 |             if ($response->successful()) {
265 |                 return ['ok' => true, 'data' => $response->json(), 'error' => null];
266 |             }
267 | 
268 |             return ['ok' => false, 'data' => null, 'error' => "NLP service returned status {$response->status()}"];
269 |         } catch (\Throwable $e) {
270 |             Log::error("Failed to connect to NLP classify service: " . $e->getMessage());
271 | 
272 |             return ['ok' => false, 'data' => null, 'error' => 'Could not reach the NLP document classifier: ' . $e->getMessage()];
273 |         }
274 |     }
