255 |     public function apply(JobApplicationRequest $request): JsonResponse    {
256 |         $jobPost = JobPost::find($request->integer('job_post_id'));
257 | 
258 |         if (! $jobPost || ! $jobPost->active || ! in_array($jobPost->status, ['published', 'Open']) || $jobPost->remainingSlots() <= 0) {
259 |             return response()->json(['message' => 'This position is no longer accepting applications. All slots have been filled.'], 422);
260 |         }
261 | 
262 |         // Scoped duplicate guard: same email + same job + active stage only.
263 |         // Same resume file used for a DIFFERENT job is always allowed.
264 |         $existing = DuplicateApplicationService::findDuplicate(
265 |             (string) $request->string('email'),
266 |             (int) $jobPost->job_post_id
267 |         );
268 |         if ($existing) {
269 |             return response()->json(
270 |                 DuplicateApplicationService::duplicateResponse($existing, (string) $jobPost->title),
271 |                 409
272 |             );
273 |         }
274 | 
275 |         $payload = [
276 |             'applicant_code' => $this->nextApplicantCode(),
277 |             'job_post_id' => $jobPost->job_post_id,
278 |             'name' => $request->string('name'),
279 |             'email' => $request->string('email'),
280 |             'phone' => $request->string('phone'),
281 |             'applied_at' => now(),
282 |             'status' => 'fit',
283 |             'stage' => 'Screened',
284 |             'source' => $request->string('source', 'Landing Page'),
285 |             'summary' => $request->string('summary'),
286 |         ];
287 | 
288 |         // Store resume file if provided — same allow-list as Recruitment Management (add applicant)
289 |         // Content hash is stored for audit; it is NOT used to block (filename/hash
290 |         // alone must never trigger a duplicate — only email+job+active stage does).
291 |         if ($request->hasFile('resume')) {
292 |             $payload['resume_hash'] = DuplicateApplicationService::hashFile($request->file('resume'));
293 |             $path = $request->file('resume')->store('resumes', 'public');
294 |             $payload['resume_file_path'] = $path;
295 |             $payload['resume_original_name'] = $request->file('resume')->getClientOriginalName();
296 |         }
297 | 
298 |         $applicant = Applicant::create($payload);
299 | 
300 |         // Run spaCy NLP screening when a resume is present — same pipeline as Recruitment Management
301 |         if (! empty($payload['resume_file_path'])) {
302 |             try {
303 |                 $managed = ManagedApplicant::find($applicant->applicant_id);
304 |                 if ($managed) {
305 |                     $this->screening->screenAndPersist($managed);
306 |                     $applicant->refresh();
307 |                 }
308 |             } catch (\Throwable $e) {
309 |                 \Illuminate\Support\Facades\Log::warning('Landing apply screening failed for applicant '.$applicant->applicant_id.': '.$e->getMessage());
310 |                 // keep applicant even if screening fails
311 |             }
312 |         }
313 | 
314 |         // Notify HR: public landing applies don't pass through the
315 |         // authenticated observer, so ring HR Admins directly (helpful-only).
316 |         NotificationService::send(
317 |             title: "New applicant from Landing: {$applicant->name}",
318 |             body: "Applied for {$jobPost->title} via Landing Page with screening score " . ($applicant->fit_score ?? 0) . "%.",
319 |             module: 'Applicant Management',
320 |             type: 'info',
321 |             targetType: 'Applicant',
322 |             targetId: (string) $applicant->applicant_id,
323 |             onlyRoleNames: ['Admin', 'Super Admin']
324 |         );
325 | 
326 |         return response()->json([
327 |             'message' => 'Application received. Our recruitment team will reach out soon.',
328 |             'data' => [
329 |                 'applicant_id' => $applicant->applicant_id,
330 |                 'applicant_code' => $applicant->applicant_code,
331 |                 'job_title' => $jobPost->title,
332 |             ],
333 |         ], 201);
334 |     }
335 | 
336 |     private function nextApplicantCode(): string
337 |     {
338 |         return DB::transaction(function () {
339 |             DB::selectOne('SELECT GET_LOCK(?, 5)', ['applicant_code_gen']);
340 |             try {
341 |                 $maxId = (int) DB::table('applicants')->max('applicant_id');
342 |                 $candidateNumber = max(1, $maxId + 1);
343 | 
344 |                 do {
345 |                     $code = 'APP-' . str_pad((string) $candidateNumber, 5, '0', STR_PAD_LEFT);
346 |                     $candidateNumber++;
347 |                 } while (Applicant::where('applicant_code', $code)->exists());
348 | 
349 |                 return $code;
350 |             } finally {
351 |                 DB::selectOne('SELECT RELEASE_LOCK(?)', ['applicant_code_gen']);
352 |             }
353 |         });
354 |     }
355 | }

