 99 |     public function jobs(Request $request): JsonResponse
100 |     {
101 |         $query = JobPost::query()
102 |             ->with(['department', 'position'])
103 |             ->whereIn('status', ['published', 'Open'])
104 |             ->where('active', 1)
105 |             // Hide fully-filled posts from the vacancy list
106 |             ->whereRaw('COALESCE(vacancies, 1) - COALESCE(filled_count, 0) > 0');
107 | 
108 |         if ($request->filled('department_id')) {
109 |             $query->where('department_id', $request->integer('department_id'));
110 |         }
111 | 
112 |         if ($request->filled('q')) {
113 |             $search = $request->string('q');
114 | 
115 |             $query->where(function ($q) use ($search) {
116 |                 $q->where('title', 'like', "%{$search}%")
117 |                     ->orWhere('summary', 'like', "%{$search}%")
118 |                     ->orWhereHas('department', fn ($d) => $d->where('name', 'like', "%{$search}%"));
119 |             });
120 |         }
121 | 
122 |         $jobs = $query->orderByDesc('posted_date')->paginate($request->integer('per_page', 25));
123 | 
124 |         return response()->json([
125 |             'data' => JobPostResource::collection($jobs),
126 |             'meta' => [
127 |                 'current_page' => $jobs->currentPage(),
128 |                 'last_page' => $jobs->lastPage(),
129 |                 'per_page' => $jobs->perPage(),
