   5 | import { clearSession, getToken } from "./auth";
   6 | 
   7 | const RAW_BASE_URL =
   8 |   (import.meta.env["VITE_API_BASE_URL"] as string) || "http://127.0.0.1:8000/api/v1";
   9 | // Normalize: "/api" + "/applicants" must join as "/api/v1/applicants" (the Vite
  10 | // dev proxy forwards /api -> Laravel), never "/api/applicants".
  11 | const BASE_URL =
  12 |   RAW_BASE_URL.replace(/\/+$/, "") +
  13 |   (RAW_BASE_URL.replace(/\/+$/, "").endsWith("/v1") ? "" : "/v1");
  14 | export const API_BASE_URL = BASE_URL;
  15 | 
  16 | /** Never show raw SQL / DB internals to users — collapse them to a generic message. */
  17 | function sanitizeErrorMessage(raw: unknown): string {
  18 |   const text = String(raw ?? "");
  19 |   if (
  20 |     /SQLSTATE|SQL:|select .* from|target machine actively refused|Connection refused|PDOException|QueryException|oxford-suites-hrms-cache/i.test(
  21 |       text,
  22 |     )
  23 |   ) {
  24 |     return "Something went wrong. Please try again later.";
  25 |   }
  26 |   return text || "Something went wrong. Please try again later.";
  27 | }
  28 | 
  29 | /* Lightweight GET cache: dedupes in-flight requests and caches responses for
  30 |    a short TTL so overlapping module fetches don't hit the server repeatedly. */
  31 | const GET_CACHE_TTL_MS = 15_000;
  32 | const getCache = new Map<string, { expiresAt: number; promise: Promise<any> }>();
  33 | 
  34 | async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
  35 |   const url = `${BASE_URL}${path.startsWith("/") ? path : `/${path}`}`;
  36 | 
  37 |   const headers: Record<string, string> = {
  38 |     Accept: "application/json",
  39 |     ...((options.headers as Record<string, string>) || {}),
  40 |   };
  41 | 
  42 |   if (typeof window !== "undefined") {
  43 |     headers["X-Current-Url"] = window.location.href;
  44 |   }
  45 | 
  46 |   const token = getToken();
  47 |   if (token) {
  48 |     headers["Authorization"] = `Bearer ${token}`;
  49 |   }
  50 | 
  51 |   if (!(options.body instanceof FormData) && options.body) {
  52 |     headers["Content-Type"] = "application/json";
  53 |   }
  54 | 
  55 |   const doFetch = async (): Promise<T> => {
  56 |     const response = await fetch(url, { ...options, headers });
  57 | 
  58 |     if (!response.ok) {
  59 |       if (response.status === 401 && typeof window !== "undefined") {
  60 |         clearSession();
  61 |         if (
  62 |           !window.location.pathname.startsWith("/login") &&
  63 |           !window.location.pathname.startsWith("/otp")
  64 |         ) {
  65 |           window.location.href = "/login";
  66 |         }
  67 |       }
  68 |       let errorData: any = null;
  69 |       try {
  70 |         errorData = await response.json();
  71 |       } catch {
  72 |         // response wasn't JSON
  73 |       }
  74 |       const message = sanitizeErrorMessage(
  75 |         errorData?.message ||
  76 |           `Request failed with status ${response.status}: ${response.statusText}`,
  77 |       );
  78 |       const error = new Error(message) as Error & {
  79 |         status?: number;
  80 |         code?: string;
  81 |         payload?: any;
  82 |         errors?: Record<string, string[]>;
  83 |       };
  84 |       error.status = response.status;
  85 |       if (errorData?.code) {
  86 |         error.code = errorData.code;
  87 |       }
  88 |       error.payload = errorData;
  89 |       if (errorData?.errors) {
  90 |         error.errors = errorData.errors;
  91 |       }
  92 |       throw error;
  93 |     }
  94 | 
  95 |     // If 204 No Content
  96 |     if (response.status === 204) {
  97 |       return {} as T;
  98 |     }
  99 | 
 100 |     // Vite proxy / SSR fallback can answer with 200 + text/html (index.html)
 101 |     // when the backend is unreachable or the dev server hasn't reloaded.
 102 |     // Fail fast as a network error (mock-data fallback) instead of a
 103 |     // confusing `JSON.parse: unexpected character` SyntaxError.
 104 |     const contentType = response.headers.get("content-type") ?? "";
 105 |     if (!contentType.includes("application/json")) {
 106 |       throw new TypeError(
 107 |         `Expected JSON but received ${contentType || "unknown content type"} (HTTP ${response.status}) for ${url}`,
 108 |       );
 109 |     }
 110 | 
 111 |     return response.json();
 112 |   };
 113 | 
 114 |   const isGet = !options.method || options.method.toUpperCase() === "GET";
 115 |   if (!isGet) {
 116 |     // Any successful write invalidates the cached GET responses so read-after-write
 117 |     // in the same session reflects the new data immediately.
 118 |     const result = await doFetch();
 119 |     getCache.clear();
 120 |     return result;
 121 |   }
 122 | 
 123 |   const cached = getCache.get(url);
 124 |   if (cached) {
 125 |     if (cached.expiresAt > Date.now()) return cached.promise;
 126 |     getCache.delete(url);
 127 |   }
 128 | 
 129 |   const promise = doFetch().catch((err) => {
 130 |     getCache.delete(url);
 131 |     throw err;
 132 |   });
 133 |   getCache.set(url, { expiresAt: Date.now() + GET_CACHE_TTL_MS, promise });
 134 |   return promise;
 135 | }
