 56 | export async function classifyOneDoc(file: File, isFirst: boolean): Promise<UnifiedDocClassify> {
 57 |   const fd = new FormData();
 58 |   fd.append("file", file);
 59 |   fd.append("is_first", isFirst ? "true" : "false");
 60 |   let res: Response;
 61 |   try {
 62 |     res = await fetch("/api/v1/landing/classify-document", {
 63 |       method: "POST",
 64 |       body: fd,
 65 |       headers: { Accept: "application/json" },
 66 |     });
 67 |   } catch {
 68 |     throw new Error("Cannot reach backend (:8000). Is `php artisan serve` running?");
 69 |   }
 70 |   const json: any = await res.json().catch(() => ({}));
 71 |   if (!res.ok || json.success === false) {
 72 |     throw new Error(json.error_message || json.message || `Classify failed (${res.status})`);
 73 |   }
 74 |   const scores: Record<string, number> =
 75 |     json.scores && typeof json.scores === "object" ? json.scores : {};
 76 |   for (const t of ["Resume", "COE", "Certificate", "Credential", "Others"]) {
 77 |     const v = Number(scores[t]);
 78 |     scores[t] = Number.isFinite(v) ? v : 0;
 79 |   }
 80 |   const signals = json.signals && typeof json.signals === "object" ? json.signals : {};
 81 |   return {
 82 |     predicted_type:
 83 |       typeof json.predicted_type === "string" && json.predicted_type ? json.predicted_type : "Others",
 84 |     confidence: Number.isFinite(Number(json.confidence)) ? Number(json.confidence) : 0,
 85 |     scores,
 86 |     reasons: Array.isArray(json.reasons) ? json.reasons.map(String) : ["No signals returned."],
 87 |     signals: {
 88 |       has_email: signals.has_email === true,
 89 |       has_phone: signals.has_phone === true,
 90 |       sections: Array.isArray(signals.sections) ? signals.sections.map(String) : [],
 91 |       char_count: Number.isFinite(Number(signals.char_count)) ? Number(signals.char_count) : 0,
 92 |     },
 93 |     text_preview: typeof json.text_preview === "string" ? json.text_preview : undefined,
 94 |     diagnostics: json.diagnostics && typeof json.diagnostics === "object" ? json.diagnostics : undefined,
 95 |     classifier_version: typeof json.classifier_version === "string" ? json.classifier_version : undefined,
 96 |   };
 97 | }
 98 | 
 99 | /** Effective type: manual override wins, else the classifier guess. */
100 | export function effectiveDocType(d: UnifiedDoc): UnifiedDocType {
101 |   if (d.manualType) return d.manualType;
102 |   const p = d.result?.predicted_type;
103 |   return (DOC_TYPES as string[]).includes(p ?? "") ? (p as UnifiedDocType) : "Others";
104 | }
105 | 
106 | /** Highest Resume-score doc (manual Resume overrides count as +inf). */
107 | export function pickResumeDoc(docs: UnifiedDoc[]): UnifiedDoc | null {
108 |   let best: UnifiedDoc | null = null;
109 |   let bestScore = 0;
110 |   for (const d of docs) {
111 |     if (d.status !== "done" || !d.result) {
112 |       if (d.manualType === "Resume") return d;
113 |       continue;
114 |     }
115 |     const s = d.manualType === "Resume" ? Number.POSITIVE_INFINITY : (d.result.scores?.["Resume"] ?? 0);
116 |     if (s > bestScore) {
117 |       bestScore = s;
118 |       best = d;
119 |     }
120 |   }
121 |   return bestScore > 0 ? best : null;
122 | }
