 99 | /** Effective type: manual override wins, else the classifier guess. */
100 | export function effectiveDocType(d: UnifiedDoc): UnifiedDocType {
101 |   if (d.manualType) return d.manualType;
102 |   const p = d.result?.predicted_type;
103 |   return (DOC_TYPES as string[]).includes(p ?? "") ? (p as UnifiedDocType) : "Others";
104 | }
105 | 
106 | /** Highest Resume-score doc (manual Resume overrides count as +inf). */
107 | export function pickResumeDoc(docs: UnifiedDoc[]): UnifiedDoc | null {
108 |   let best: UnifiedDoc | null = null;
109 |   let bestScore = 0;
110 |   for (const d of docs) {
111 |     if (d.status !== "done" || !d.result) {
112 |       if (d.manualType === "Resume") return d;
113 |       continue;
114 |     }
115 |     const s = d.manualType === "Resume" ? Number.POSITIVE_INFINITY : (d.result.scores?.["Resume"] ?? 0);
116 |     if (s > bestScore) {
117 |       bestScore = s;
118 |       best = d;
119 |     }
120 |   }
121 |   return bestScore > 0 ? best : null;
122 | }
